                  alignItems: "center",
                  gap: "10px",
                  cursor: "pointer",
                  p: "5px 12px 5px 5px",
                  borderRadius: "24px",
                  background: "rgba(255, 255, 255, 0.14)",
                  transition: "background 0.15s",
                  "&:hover": {
                    background: "rgba(255, 255, 255, 0.26)",
                  },
                }}
              >
                <Avatar
                  sx={{
                    bgcolor: "#ffffff",
                    color: "#4F46E5",
                    width: 34,
                    height: 34,
                    fontSize: "13px",
                    fontWeight: 700,
                  }}
                >
                  {getInitials(user?.fullName || user?.username)}
                </Avatar>
                <Box sx={{ display: { xs: "none", sm: "block" }, lineHeight: 1.1 }}>
                  <Typography
                    sx={{
                      fontSize: "13px",
                      fontWeight: 600,
                      color: "#ffffff",
                    }}
                  >
                    {user?.fullName || user?.username || "Usuario"}
                  </Typography>
                  <Typography
                    sx={{
                      fontSize: "11px",
                      opacity: 0.8,
                      color: "#ffffff",
                    }}
                  >
                    {user?.roles?.[0] || "Administrador"}
                  </Typography>
                </Box>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M6 9l6 6 6-6" />
                </svg>
              </Box>

              <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={handleUserMenuClose}
                anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
                transformOrigin={{ vertical: "top", horizontal: "right" }}
                PaperProps={{
                  sx: {
                    mt: 1,
                    minWidth: 180,
                    boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
                    borderRadius: 3,
                  },
                }}
              >
                <MenuItem disabled sx={{ opacity: 0.8, fontSize: "0.85rem", fontWeight: 600 }}>
                  Sesión: {user?.roles?.[0] || "Ninguno"}
                </MenuItem>
                <Divider />
                <LogoutButton onClose={handleUserMenuClose} />
              </Menu>
            </Box>
          </Toolbar>
        </AppBar>

        {/* Drawer único para todos los dispositivos (temporal) */}
        <Drawer
          variant="temporary"
          open={open}
          onClose={handleDrawerToggle}
          ModalProps={{ keepMounted: true }}
          sx={{
            "& .MuiDrawer-paper": {
              boxSizing: "border-box",
              width: drawerWidth,
              borderRight: "1px solid",
              borderColor: "divider",
              bgcolor: "background.paper",
            },
          }}
        >
          <Toolbar sx={{ display: "flex", justifyContent: "space-between", px: 2 }}>
            <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
              <Box
                sx={{
                  width: 32,
                  height: 32,
                  borderRadius: 1.5,
                  bgcolor: "primary.main",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 16,
                }}
              >
                🛡️
              </Box>
              <Typography variant="h6" sx={{ fontWeight: 800, color: "text.primary" }}>
                San Cristóbal
              </Typography>
            </Box>
            <IconButton onClick={handleDrawerToggle}>
              <CloseIcon />
            </IconButton>
          </Toolbar>
          <Divider />
          <Navigation onNavigate={handleDrawerToggle} />
