          onDownloadPdf={async () => {
            try {
              await descargarPdfInspeccionesEmergenciaCliente(row._id);
            } catch (err) {
              console.error(err);
            }
          }}
          onDownloadExcel={async () => {
            try {
              await descargarExcelInspeccionesEmergenciaCliente(row._id);
            } catch (err) {
              console.error(err);
            }
          }}
        />
